modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator;
end Baseline;
model FINDING00847
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(C=0);
end FINDING00847;
model FINDING00853
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(f=0);
end FINDING00853;
model FINDING00846
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(L=0);
end FINDING00846;
model FINDING00848
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(R=0);
end FINDING00848;
model FinalFINDING00847
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(final C=0);
end FinalFINDING00847;
model FinalFINDING00853
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(final f=0);
end FinalFINDING00853;
model FinalFINDING00846
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(final L=0);
end FinalFINDING00846;
model FinalFINDING00848
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(final R=0);
end FinalFINDING00848;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00847\n");
simulate(FINDING00847, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00853\n");
simulate(FINDING00853, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00846\n");
simulate(FINDING00846, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00848\n");
simulate(FINDING00848, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00847\n");
simulate(FinalFINDING00847, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00853\n");
simulate(FinalFINDING00853, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00846\n");
simulate(FinalFINDING00846, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00848\n");
simulate(FinalFINDING00848, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00847\n");
system("./Baseline -override C=0 -r=FINDING00847_override.csv");
print("AUDIT_OVERRIDE FINDING00853\n");
system("./Baseline -override f=0 -r=FINDING00853_override.csv");
print("AUDIT_OVERRIDE FINDING00846\n");
system("./Baseline -override L=0 -r=FINDING00846_override.csv");
print("AUDIT_OVERRIDE FINDING00848\n");
system("./Baseline -override R=0 -r=FINDING00848_override.csv");
